const text = $('Telegram Trigger').first().json.message.text.trim();
const pending = $('Get row(s)6').first().json;

const match = text.match(/^(\d{1,2}):(\d{2})(?:\s*[-–]\s*(\d{1,2}):(\d{2}))?$/);

if (!match) {
  throw new Error('Введите время в формате 18:30 или 18:00–19:00');
}

const fromHour = Number(match[1]);
const fromMinute = Number(match[2]);

if (fromHour > 23 || fromMinute > 59) {
  throw new Error('Некорректное время');
}

const from = `${String(fromHour).padStart(2, '0')}:${String(fromMinute).padStart(2, '0')}`;

let to = null;

if (match[3]) {
  const toHour = Number(match[3]);
  const toMinute = Number(match[4]);

  if (toHour > 23 || toMinute > 59) {
    throw new Error('Некорректное конечное время');
  }

  to = `${String(toHour).padStart(2, '0')}:${String(toMinute).padStart(2, '0')}`;
}

return [{
  json: {
    request_id: pending.request_id,
    message_id: pending.message_id,
    preferred_time_from: from,
    pending_action_id: pending.id,
    preferred_time_to: to
  }
}];

